57	        // Number of invokers
58	        int length = invokers.size();
59	
60	        if (!needWeightLoadBalance(invokers, invocation)) {
61	            return invokers.get(ThreadLocalRandom.current().nextInt(length));
62	        }
63	
64	        // Every invoker has the same weight?
65	        boolean sameWeight = true;
66	        // the maxWeight of every invoker, the minWeight = 0 or the maxWeight of the last invoker
67	        int[] weights = new int[length];
68	        // The sum of weights
69	        int totalWeight = 0;
70	        for (int i = 0; i < length; i++) {
71	            int weight = getWeight(invokers.get(i), invocation);
72	            // Sum
73	            totalWeight += weight;
74	            // save for later use
75	            weights[i] = totalWeight;
76	            if (sameWeight && totalWeight != weight * (i + 1)) {
77	                sameWeight = false;
78	            }
79	        }
80	        if (totalWeight > 0 && !sameWeight) {
81	            // If (not every invoker has the same weight & at least one invoker's weight>0), select randomly based on
82	            // totalWeight.
83	            int offset = ThreadLocalRandom.current().nextInt(totalWeight);
84	            // Return an invoker based on the random value.
85	            if (length <= 4) {
86	                for (int i = 0; i < length; i++) {
87	                    if (offset < weights[i]) {
88	                        return invokers.get(i);
89	                    }
90	                }
91	            } else {
92	                int i = Arrays.binarySearch(weights, offset);
